import{_ as t,o,c as a,a6 as i}from"./chunks/framework.DtfPIzdJ.js";const p=JSON.parse('{"title":"Tutorial: build an AI helpdesk","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md"}'),r={name:"tutorial/index.md"};function s(n,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="tutorial-build-an-ai-helpdesk" tabindex="-1">Tutorial: build an AI helpdesk <a class="header-anchor" href="#tutorial-build-an-ai-helpdesk" aria-label="Permalink to &quot;Tutorial: build an AI helpdesk&quot;">​</a></h1><p>In this tutorial you build a complete, working <strong>Helpdesk</strong> app in Cluub, from an empty folder to a production build. It takes about an hour and a half if you follow every step, and every line of code is shown.</p><p>You don&#39;t need to know Cluub yet. If you&#39;ve written a little JavaScript, Python or similar, you know enough. Each new idea is explained the first time it shows up, with a link to the reference page if you want the details.</p><h2 id="what-you-ll-build" tabindex="-1">What you&#39;ll build <a class="header-anchor" href="#what-you-ll-build" aria-label="Permalink to &quot;What you&#39;ll build&quot;">​</a></h2><p>A small support desk for a software company. It has two kinds of users:</p><ul><li><strong>Customers</strong> fill in a form to send a support ticket and get a ticket number back.</li><li><strong>Agents</strong> work through a queue of open tickets, start working on one, and resolve it with a note that says how they fixed it.</li></ul><p>AI does the boring parts:</p><ul><li>When a ticket arrives, AI decides its <strong>priority</strong> (<code>low</code>, <code>normal</code>, <code>high</code>, <code>urgent</code>) and <strong>category</strong> (<code>billing</code>, <code>technical</code>, <code>account</code>, <code>other</code>), and writes a one-sentence <strong>summary</strong> for the agents.</li><li>Agents can paste a raw customer <strong>email</strong>, and AI pulls out the name, email address, subject and problem to create a ticket from it.</li><li>If the AI is unavailable, tickets still come in. They just aren&#39;t triaged.</li></ul><p>When you&#39;re done, the app has:</p><table tabindex="0"><thead><tr><th>Part</th><th>What it is</th></tr></thead><tbody><tr><td>2 models</td><td><code>Ticket</code> and <code>TicketDraft</code>, with validation rules</td></tr><tr><td>1 store</td><td><code>Tickets</code>, saved to <code>storage/tickets.json</code></td></tr><tr><td>2 services</td><td><code>TicketService</code> (business rules) and <code>TriageService</code> (AI)</td></tr><tr><td>1 api</td><td><code>TicketApi</code>, six HTTP endpoints under <code>/api/tickets</code></td></tr><tr><td>4 pages</td><td>the ticket form, the queue, a ticket detail page and an email import page</td></tr><tr><td>1 component, 1 layout</td><td><code>TicketRow</code> and <code>Main</code></td></tr><tr><td>61 tests</td><td>13 you write yourself, 48 that Cluub writes for you</td></tr></tbody></table><p>Along the way you&#39;ll use most of the language: models and rules, stores, services with <code>require</code> and <code>fail</code>, apis with path parameters, pages with state and actions, components, layouts, <code>ask ai</code> in all three forms, generated and hand-written tests, <code>cluub explain</code>, <code>cluub build</code> and <code>cluub start</code>.</p><h2 id="the-final-result" tabindex="-1">The final result <a class="header-anchor" href="#the-final-result" aria-label="Permalink to &quot;The final result&quot;">​</a></h2><p>Open the app in a browser and you see a header with <strong>Helpdesk · New ticket · Queue · Import email</strong>.</p><ul><li><strong>New ticket</strong> (<code>/</code>): a &quot;Contact support&quot; form with name, email, subject and a message box. Submitting shows &quot;Thanks, Ada Lovelace! Your ticket number is #1.&quot;</li><li><strong>Queue</strong> (<code>/queue</code>): one card per open ticket, most urgent first. Each card shows badges for priority, category and status, the subject, who sent it, the AI summary, and <strong>Open</strong> / <strong>Start</strong> buttons.</li><li><strong>Ticket detail</strong> (<code>/tickets/1</code>): the whole ticket, the AI summary, a <strong>Start working</strong> button, and a box to write the resolution and <strong>Resolve ticket</strong>.</li><li><strong>Import email</strong> (<code>/import</code>): paste an email, click <strong>Create ticket</strong>, and get a link to the new ticket.</li></ul><p>Bad input never slips through. Try to submit a ticket with the email <code>nope</code> and a red message says <em>&quot;customerEmail must be a valid email address&quot;</em>. You don&#39;t write any code for that message.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You need:</p><ul><li><strong>Node.js 18 or newer.</strong></li><li><strong>The <code>cluub</code> command.</strong> See <a href="/home/guide/install">Install &amp; first app</a>. Check it with <code>cluub version</code>, which prints <code>cluub 0.1.0</code>.</li><li><strong>A terminal and a text editor.</strong> Syntax highlighting for <code>.clb</code> files is in <code>editors/cluub.tmLanguage.json</code>.</li><li><strong>Optional: an AI key</strong> for chapter 6, such as an <code>ANTHROPIC_API_KEY</code> for Claude. Everything else, including all the tests, works without one.</li></ul><p>It helps to have read the <a href="/home/guide/tour">10-minute tour</a>, but it isn&#39;t required.</p><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><ol><li><a href="/home/tutorial/01-setup">Create the project</a>: <code>cluub new</code>, <code>cluub dev</code>, your first page and your first compile error.</li><li><a href="/home/tutorial/02-ticket-model">The Ticket model</a>: describe the data and its validation rules.</li><li><a href="/home/tutorial/03-store-and-service">A store and a service</a>: save tickets and write the business rules.</li><li><a href="/home/tutorial/04-api">The api</a>: HTTP endpoints, path parameters and automatic input checks.</li><li><a href="/home/tutorial/05-pages-and-components">Pages, components and a layout</a>: the ticket form, the queue and the ticket detail page.</li><li><a href="/home/tutorial/06-ai-features">AI features</a>: classify with <code>as one of</code>, summarize with <code>ask ai</code>, extract with <code>as Model</code>.</li><li><a href="/home/tutorial/07-testing">Testing</a>: read the generated tests, then write your own UI, api and service tests.</li><li><a href="/home/tutorial/08-share-and-ship">Share and ship</a>: <code>cluub explain</code> for the team, <code>cluub build</code>, <code>cluub start</code>, and what to try next.</li></ol><h2 id="how-to-follow-along" tabindex="-1">How to follow along <a class="header-anchor" href="#how-to-follow-along" aria-label="Permalink to &quot;How to follow along&quot;">​</a></h2><p>Every code block says which file it belongs to, for example &quot;Create <code>models/ticket.clb</code>&quot;. When a later chapter changes a file, it shows the <strong>whole</strong> new version of that file, so you can replace the contents rather than hunt for the changed lines.</p><p>Each chapter ends with a <strong>Checkpoint</strong> that says what you should see in the terminal and the browser. Timings like <code>checked in 2.4ms</code> differ from machine to machine; everything else should match. If something doesn&#39;t, run <code>cluub check</code>. It names the file, the line and usually the fix.</p><p>Ready? Start with <a href="/home/tutorial/01-setup">chapter 1: Create the project</a>.</p>',25)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
